WITH truth AS (SELECT a.ACCOUNT_ID A, b.ACCOUNT_ID B FROM RIPPLE_GT.ACCOUNT_OWNERS a JOIN RIPPLE_GT.ACCOUNT_OWNERS b ON a.PERSON_ID=b.PERSON_ID AND a.ACCOUNT_ID<b.ACCOUNT_ID),
miss AS (SELECT t.* FROM truth t JOIN RIPPLE.ACCOUNT_PERSON pa ON pa.ACCOUNT_ID=t.A JOIN RIPPLE.ACCOUNT_PERSON pb ON pb.ACCOUNT_ID=t.B WHERE pa.PERSON_ID<>pb.PERSON_ID)
SELECT CASE WHEN p.A IS NULL THEN 'not_candidate' ELSE p.NAME_AGREE||' pin='||p.PIN_EQ||' score='||p.SCORE END AS WHY, COUNT(*) N
FROM miss m LEFT JOIN RIPPLE.ID_PAIRS p ON p.A=m.A AND p.B=m.B GROUP BY 1 ORDER BY 2 DESC LIMIT 12;
WITH c AS (SELECT p.*, CASE WHEN ga.PERSON_ID=gb.PERSON_ID THEN 1 ELSE 0 END T FROM RIPPLE.ID_PAIRS p JOIN RIPPLE_GT.ACCOUNT_OWNERS ga ON ga.ACCOUNT_ID=p.A JOIN RIPPLE_GT.ACCOUNT_OWNERS gb ON gb.ACCOUNT_ID=p.B WHERE p.SCORE<6)
SELECT NAME_AGREE, PIN_EQ, PHONE_EQ, EMAIL_EQ, COUNT(*) N, SUM(T) TRUE_N FROM c GROUP BY 1,2,3,4 ORDER BY N DESC LIMIT 10;
